function Demo() {
  return (
    <Accordion defaultValue="spring">
      <Accordion.Item value="spring">
        <Accordion.Trigger>Spring</Accordion.Trigger>
        <Accordion.Panel>Long rains and the first green on the hills.</Accordion.Panel>
      </Accordion.Item>
      <Accordion.Item value="summer">
        <Accordion.Trigger>Summer</Accordion.Trigger>
        <Accordion.Panel>Warm nights and slow evenings.</Accordion.Panel>
      </Accordion.Item>
      <Accordion.Item value="autumn">
        <Accordion.Trigger>Autumn</Accordion.Trigger>
        <Accordion.Panel>Short days and a sharp wind.</Accordion.Panel>
      </Accordion.Item>
    </Accordion>
  );
}`,view:()=>i(on,{defaultValue:"spring"},i(on.Item,{value:"spring"},i(on.Trigger,null,"Spring"),i(on.Panel,null,"Long rains and the first green on the hills.")),i(on.Item,{value:"summer"},i(on.Trigger,null,"Summer"),i(on.Panel,null,"Warm nights and slow evenings.")),i(on.Item,{value:"autumn"},i(on.Trigger,null,"Autumn"),i(on.Panel,null,"Short days and a sharp wind."))),height:230},{title:"Variants",code:`
const VARIANTS = ['plain', 'boxed', 'soft', 'split'];

function Demo() {
  const variant = $signal($active(), 'boxed');
  return (
    <Stack gap="sm">
      <Row gap="xs">
        {VARIANTS.map(v => (
          <Button size="xs" variant={() => ($read(variant) === v ? 'solid' : 'neutral')} onPress={() => $write(variant, v)}>{v}</Button>
        ))}
      </Row>
      <Accordion variant={() => $read(variant)} defaultValue="first" radius="md">
        <Accordion.Item value="first">
          <Accordion.Trigger>Opening hours</Accordion.Trigger>
          <Accordion.Panel>Nine to six, closed on Sundays.</Accordion.Panel>
        </Accordion.Item>
        <Accordion.Item value="second">
          <Accordion.Trigger>Getting here</Accordion.Trigger>
          <Accordion.Panel>Two stops past the river, then left.</Accordion.Panel>
        </Accordion.Item>
      </Accordion>
    </Stack>
  );
}`,view:()=>{let e=z(A(),"boxed");return i(D,{gap:"sm"},i(W,{gap:"xs"},G7.map(t=>i(K,{size:"xs",variant:()=>g(e)===t?"solid":"neutral",onPress:()=>v(e,t)},t))),i(on,{variant:()=>g(e),defaultValue:"first",radius:"md"},i(on.Item,{value:"first"},i(on.Trigger,null,"Opening hours"),i(on.Panel,null,"Nine to six, closed on Sundays.")),i(on.Item,{value:"second"},i(on.Trigger,null,"Getting here"),i(on.Panel,null,"Two stops past the river, then left."))))},height:230},{title:"Multiple, held by a signal, chevron at the start",code:`
