function Demo() {
  const active = $signal($active(), 0);
  const go = to => $write(active, Math.min(3, Math.max(0, to)));
  return (
    <Stack gap="md">
      <Stepper value={active} onChange={i => go(i)} reach="any">
        <Stepper.Stage label="Cart" description="3 items">Two notebooks and a pen, \u20AC 24.</Stepper.Stage>
        <Stepper.Stage label="Address" description="Where it goes">Delivery to 12 Harbor Lane.</Stepper.Stage>
        <Stepper.Stage label="Payment" description="Card or transfer">The card ending in 4417.</Stepper.Stage>
        <Stepper.Done>Done: the order is placed.</Stepper.Done>
      </Stepper>
      <Row gap="xs" justify="center">
        <Button variant="neutral" onPress={() => go($read(active) - 1)}>Previous</Button>
        <Button onPress={() => go($read(active) + 1)}>Continue</Button>
      </Row>
      <Text size="sm" fg="quiet">{() => 'value: ' + $read(active)}</Text>
    </Stack>
  );
}`,view:()=>{let e=z(A(),0),t=n=>v(e,Math.min(3,Math.max(0,n)));return i(D,{gap:"md"},i(no,{value:e,onChange:n=>t(n),reach:"any"},i(no.Stage,{label:"Cart",description:"3 items"},"Two notebooks and a pen, \u20AC 24."),i(no.Stage,{label:"Address",description:"Where it goes"},"Delivery to 12 Harbor Lane."),i(no.Stage,{label:"Payment",description:"Card or transfer"},"The card ending in 4417."),i(no.Done,null,"Done: the order is placed.")),i(W,{gap:"xs",justify:"center"},i(K,{variant:"neutral",onPress:()=>t(g(e)-1)},"Previous"),i(K,{onPress:()=>t(g(e)+1)},"Continue")),i(M,{size:"sm",fg:"quiet"},()=>"value: "+g(e)))},height:220},{title:"Vertical, pressing back to a done stage",code:`
